#!/usr/bin/env python3
"""Merge user data from JSON, CSV and Parquet sources with priority resolution."""
import csv
import json
import os
import re
from datetime import datetime, date

import pandas as pd

SOURCES = [
    ("source_a", "/data/source_a/users.json"),
    ("source_b", "/data/source_b/users.csv"),
    ("source_c", "/data/source_c/users.parquet"),
]

FIELD_MAP = {
    "user_id": "user_id", "id": "user_id", "userid": "user_id", "uid": "user_id",
    "email": "email", "email_address": "email", "emailaddress": "email", "mail": "email",
    "full_name": "name", "name": "name", "username": "name", "user_name": "name",
    "fullname": "name",
    "registration_date": "created_date", "created_at": "created_date",
    "joined": "created_date", "createddate": "created_date", "created_date": "created_date",
    "joined_date": "created_date", "signup_date": "created_date",
    "status": "status", "is_active": "status", "active": "status", "isactive": "status",
    "state": "status",
}

FIELDS = ["name", "email", "created_date", "status"]


def canon(key):
    k = re.sub(r"[^a-z0-9]", "", str(key).lower())
    return FIELD_MAP.get(str(key).strip().lower(), FIELD_MAP.get(k))


def norm_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, (datetime, date)):
        return v.strftime("%Y-%m-%d")
    if isinstance(v, pd.Timestamp):
        return v.strftime("%Y-%m-%d")
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d-%m-%Y", "%d/%m/%Y", "%m/%d/%Y",
                "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%d %b %Y", "%B %d, %Y",
                "%b %d, %Y", "%Y%m%d"):
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            pass
    try:
        ts = pd.to_datetime(s, errors="coerce")
        if pd.notna(ts):
            return ts.strftime("%Y-%m-%d")
    except Exception:
        pass
    return s


def norm_status(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, bool):
        return "active" if v else "inactive"
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    low = s.lower()
    if low in ("true", "1", "yes", "y", "t"):
        return "active"
    if low in ("false", "0", "no", "n", "f"):
        return "inactive"
    return low


def norm_text(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    return s


def norm_id(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    try:
        return int(str(v).strip())
    except (ValueError, TypeError):
        return None


def normalize(raw):
    """raw dict -> (user_id, {field: value}) using field mapping."""
    rec = {}
    uid = None
    for k, v in raw.items():
        f = canon(k)
        if f is None:
            continue
        if f == "user_id":
            uid = norm_id(v)
        elif f == "created_date":
            rec[f] = norm_date(v)
        elif f == "status":
            rec[f] = norm_status(v)
        else:
            rec[f] = norm_text(v)
    return uid, {k: v for k, v in rec.items() if v is not None}


def load_json(path):
    with open(path) as fh:
        data = json.load(fh)
    if isinstance(data, dict):
        for key in ("users", "data", "records", "items"):
            if isinstance(data.get(key), list):
                data = data[key]
                break
        else:
            data = [data]
    return [r for r in data if isinstance(r, dict)]


def load_csv(path):
    with open(path, newline="") as fh:
        return [dict(r) for r in csv.DictReader(fh)]


def load_parquet(path):
    df = pd.read_parquet(path)
    return df.to_dict(orient="records")


def load(path):
    ext = os.path.splitext(path)[1].lower()
    if ext == ".json":
        return load_json(path)
    if ext in (".csv", ".tsv"):
        return load_csv(path)
    return load_parquet(path)


def main():
    per_source = {}   # name -> {uid: record}
    order = []
    for name, path in SOURCES:
        order.append(name)
        recs = {}
        if os.path.exists(path):
            for raw in load(path):
                uid, rec = normalize(raw)
                if uid is None:
                    continue
                if uid in recs:
                    recs[uid].update(rec)
                else:
                    recs[uid] = rec
        per_source[name] = recs

    all_ids = sorted({uid for recs in per_source.values() for uid in recs})

    merged = []
    conflicts = []
    for uid in all_ids:
        out = {"user_id": uid}
        for field in FIELDS:
            values = {}
            for src in order:
                rec = per_source[src].get(uid)
                if rec is not None and field in rec:
                    values[src] = rec[field]
            if not values:
                out[field] = None
                continue
            selected = next(values[s] for s in order if s in values)
            out[field] = selected
            if len(set(values.values())) > 1:
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": {s: values[s] for s in order if s in values},
                    "selected": selected,
                })
        merged.append(out)

    df = pd.DataFrame(merged, columns=["user_id", "name", "email", "created_date", "status"])
    df["user_id"] = df["user_id"].astype("int64")
    for col in ("name", "email", "created_date", "status"):
        df[col] = df[col].astype(object).where(df[col].notna(), None)
    os.makedirs("/app", exist_ok=True)
    df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as fh:
        json.dump(report, fh, indent=2)

    print(df.to_string(index=False))
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()

